package com.yunpan.appmanage.carui;

import android.app.Activity;
import android.app.Dialog;
import android.content.DialogInterface;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Matrix;
import android.graphics.Paint;
import android.graphics.Path;
import android.graphics.RectF;
import android.net.Uri;
import android.view.Gravity;
import android.view.MotionEvent;
import android.view.ScaleGestureDetector;
import android.view.View;
import android.view.Window;
import android.widget.LinearLayout;
import android.widget.TextView;
import java.io.InputStream;
import java.io.File;
import java.io.FileOutputStream;

/** Screen-ratio crop with pan/pinch; only creates a private copy, never edits the selected file. */
final class WallpaperCropper {
    static void show(final Activity a,final Uri source,final Wallpapers.Config draft,final String grant){final java.util.concurrent.atomic.AtomicBoolean canceled=new java.util.concurrent.atomic.AtomicBoolean();final android.app.ProgressDialog loading=new android.app.ProgressDialog(a);loading.setMessage("正在读取图片…");loading.setCancelable(true);loading.setOnCancelListener(new DialogInterface.OnCancelListener(){@Override public void onCancel(DialogInterface d){canceled.set(true);if(!a.isFinishing())WallpaperPicker.show(a,draft,grant);}});loading.show();CarUi.theme(loading.getWindow().getDecorView());CarUi.decorateDialog(loading);new Thread(new Runnable(){@Override public void run(){Bitmap decoded=null;try{decoded=decode(a,source);}catch(Exception|OutOfMemoryError ignored){}final Bitmap image=decoded;a.runOnUiThread(new Runnable(){@Override public void run(){loading.dismiss();if(canceled.get()||a.isFinishing()||android.os.Build.VERSION.SDK_INT>=17&&a.isDestroyed()){if(image!=null)image.recycle();return;}if(image==null){CarUi.message(a,"无法读取图片，请换用 JPG、PNG 或设备支持的图片格式");WallpaperPicker.show(a,draft,grant);}else new Editor(a,image,draft,grant).show();}});}},"wallpaper-image-decode").start();}
    static Bitmap decode(Activity a,Uri uri)throws Exception{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;try(InputStream in=a.getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,o);}if(o.outWidth<=0||o.outHeight<=0)return null;o.inSampleSize=1;while(Math.max(o.outWidth,o.outHeight)/o.inSampleSize>4096||(long)(o.outWidth/o.inSampleSize)*(o.outHeight/o.inSampleSize)>8000000)o.inSampleSize*=2;o.inJustDecodeBounds=false;o.inPreferredConfig=Bitmap.Config.RGB_565;Bitmap bitmap;try(InputStream in=a.getContentResolver().openInputStream(uri)){bitmap=BitmapFactory.decodeStream(in,null,o);}if(bitmap!=null&&android.os.Build.VERSION.SDK_INT>=24)try(InputStream in=a.getContentResolver().openInputStream(uri)){int orientation=new android.media.ExifInterface(in).getAttributeInt(android.media.ExifInterface.TAG_ORIENTATION,1);Matrix m=new Matrix();switch(orientation){case 2:m.setScale(-1,1);break;case 3:m.setRotate(180);break;case 4:m.setScale(1,-1);break;case 5:m.setRotate(90);m.postScale(-1,1);break;case 6:m.setRotate(90);break;case 7:m.setRotate(-90);m.postScale(-1,1);break;case 8:m.setRotate(-90);break;}if(!m.isIdentity()){Bitmap rotated=Bitmap.createBitmap(bitmap,0,0,bitmap.getWidth(),bitmap.getHeight(),m,true);if(rotated!=bitmap)bitmap.recycle();bitmap=rotated;}}catch(java.io.IOException|RuntimeException ignored){}return bitmap;}
    static boolean resize(Dialog d){if(!(d instanceof Editor))return false;((Editor)d).resize();return true;}
    private static final class Editor extends Dialog {
        final Activity activity;final Wallpapers.Config draft;final String grant;final CropView crop;final TextView dimensions;final CarUi.Skin skin;
        Editor(Activity a,Bitmap image,Wallpapers.Config draft,String grant){super(a);this.activity=a;this.draft=draft.copy();this.grant=grant;skin=CarUi.skin(a);requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout panel=new LinearLayout(a);panel.setOrientation(1);panel.setTag(CarUi.OWN);panel.setPadding(d(20),d(16),d(20),d(16));TextView title=CarUi.text(a,"裁切静态壁纸",25,skin.ink,true);panel.addView(title);dimensions=CarUi.text(a,"",16,skin.muted,false);dimensions.setPadding(0,d(8),0,d(10));panel.addView(dimensions);int[] target=CarUi.windowBounds(a);crop=new CropView(a,image,target[0],target[1]);panel.addView(crop,new LinearLayout.LayoutParams(-1,0,1));TextView help=CarUi.text(a,"拖动调整位置 · 双指缩放 · 亮框内为最终画面",15,skin.muted,false);help.setPadding(0,d(10),0,d(10));panel.addView(help);LinearLayout footer=new LinearLayout(a);footer.setGravity(Gravity.CENTER_VERTICAL);footer.addView(button("取消",new View.OnClickListener(){@Override public void onClick(View v){back();}}),new LinearLayout.LayoutParams(0,-2,1));footer.addView(button("重置",new View.OnClickListener(){@Override public void onClick(View v){crop.reset();}}),new LinearLayout.LayoutParams(0,-2,1));TextView use=button("使用裁切",new View.OnClickListener(){@Override public void onClick(View v){use();}});use.setTextColor(skin.onAccent);use.setBackground(CarUi.buttonBackground(a,skin.accent,skin.pressedAccent,skin.onAccent,20));footer.addView(use,new LinearLayout.LayoutParams(0,-2,1));panel.addView(footer);setContentView(panel);setOnCancelListener(new DialogInterface.OnCancelListener(){@Override public void onCancel(DialogInterface d){WallpaperPicker.show(activity,Editor.this.draft,Editor.this.grant);}});}
        int d(int n){return CarUi.dp(activity,n);}TextView button(String name,View.OnClickListener action){TextView t=CarUi.text(activity,name,18,skin.ink,true);t.setGravity(Gravity.CENTER);t.setMinimumHeight(d(52));t.setPadding(d(12),d(12),d(12),d(12));t.setFocusable(true);t.setClickable(true);t.setBackground(CarUi.buttonBackground(activity,skin.soft,skin.surface,skin.ink,20));t.setOnClickListener(action);return t;}
        void back(){dismiss();WallpaperPicker.show(activity,draft,grant);}
        void use(){File file=null;Bitmap output=null;try{output=crop.output();File dir=new File(activity.getFilesDir(),"wallpaper-images");if(!dir.isDirectory()&&!dir.mkdirs())throw new java.io.IOException();file=new File(dir,java.util.UUID.randomUUID().toString()+".jpg");try(FileOutputStream stream=new FileOutputStream(file)){if(!output.compress(Bitmap.CompressFormat.JPEG,92,stream))throw new java.io.IOException();}Wallpapers.discardImage(activity,draft.imageUri);draft.imageUri=Uri.fromFile(file).toString();draft.staticImage=3;draft.mode="static";dismiss();WallpaperPicker.show(activity,draft,grant);}catch(Exception|OutOfMemoryError e){if(file!=null)file.delete();CarUi.message(activity,"裁切未保存，请缩小图片或释放存储空间后重试");}finally{if(output!=null)output.recycle();}}
        void resize(){int[] target=CarUi.windowBounds(activity);getWindow().setLayout(target[0]-d(32),target[1]-d(40));crop.target(target[0],target[1]);int[] output=outputSize(target[0],target[1]);dimensions.setText("目标屏幕："+target[0]+" × "+target[1]+(output[0]!=target[0]||output[1]!=target[1]?" · 输出："+output[0]+" × "+output[1]:""));}
        @Override public void show(){super.show();resize();CarUi.decorateDialog(this);}
        @Override public void dismiss(){super.dismiss();crop.release();}
    }
    static int[] outputSize(int w,int h){float factor=Math.min(1,Math.min(2560f/Math.max(w,h),(float)Math.sqrt(4000000d/((double)w*h))));return new int[]{Math.max(1,Math.round(w*factor)),Math.max(1,Math.round(h*factor))};}
    static final class CropView extends View {
        Bitmap image;final RectF frame=new RectF();final Paint paint=new Paint(3);final ScaleGestureDetector detector;int targetW,targetH;float scale,minScale,dx,dy,lastX,lastY;
        CropView(Activity a,Bitmap image,int w,int h){super(a);this.image=image;targetW=w;targetH=h;setContentDescription("图片裁切区域，可拖动和双指缩放，方向键移动，加减键缩放");setFocusable(true);setFocusableInTouchMode(true);detector=new ScaleGestureDetector(a,new ScaleGestureDetector.SimpleOnScaleGestureListener(){@Override public boolean onScale(ScaleGestureDetector d){zoom(d.getScaleFactor(),d.getFocusX(),d.getFocusY());return true;}});}
        void target(int w,int h){if(w==targetW&&h==targetH)return;targetW=w;targetH=h;calculate();}
        @Override protected void onSizeChanged(int w,int h,int ow,int oh){calculate();}
        void calculate(){if(image==null||getWidth()==0||getHeight()==0)return;float availableW=Math.max(1,getWidth()-CarUi.dp(getContext(),24)),availableH=Math.max(1,getHeight()-CarUi.dp(getContext(),24)),width=Math.min(availableW,availableH*targetW/targetH),height=width*targetH/targetW;float cx=scale>0?(frame.centerX()-dx)/scale:image.getWidth()/2f,cy=scale>0?(frame.centerY()-dy)/scale:image.getHeight()/2f,ratio=minScale>0?scale/minScale:1;frame.set((getWidth()-width)/2,(getHeight()-height)/2,(getWidth()+width)/2,(getHeight()+height)/2);minScale=Math.max(frame.width()/image.getWidth(),frame.height()/image.getHeight());scale=Math.max(minScale,Math.min(minScale*8,minScale*ratio));dx=frame.centerX()-cx*scale;dy=frame.centerY()-cy*scale;constrain();invalidate();}
        void reset(){if(image==null)return;minScale=Math.max(frame.width()/image.getWidth(),frame.height()/image.getHeight());scale=minScale;dx=frame.centerX()-image.getWidth()*scale/2;dy=frame.centerY()-image.getHeight()*scale/2;constrain();invalidate();}
        void move(float x,float y){dx+=x;dy+=y;constrain();invalidate();}
        void zoom(float factor,float x,float y){float next=Math.max(minScale,Math.min(minScale*8,scale*factor));if(scale>0){dx=x-(x-dx)*next/scale;dy=y-(y-dy)*next/scale;}scale=next;constrain();invalidate();}
        void constrain(){if(image==null)return;dx=Math.max(frame.right-image.getWidth()*scale,Math.min(frame.left,dx));dy=Math.max(frame.bottom-image.getHeight()*scale,Math.min(frame.top,dy));}
        Matrix matrix(){Matrix m=new Matrix();m.setScale(scale,scale);m.postTranslate(dx,dy);return m;}
        @Override protected void onDraw(Canvas c){c.drawColor(Color.BLACK);if(image==null||frame.width()==0)return;paint.setColor(Color.WHITE);paint.setStyle(Paint.Style.FILL);c.drawBitmap(image,matrix(),paint);Path shade=new Path();shade.setFillType(Path.FillType.EVEN_ODD);shade.addRect(0,0,getWidth(),getHeight(),Path.Direction.CW);shade.addRect(frame,Path.Direction.CW);paint.setColor(0xA6000000);c.drawPath(shade,paint);paint.setColor(Color.WHITE);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(CarUi.dp(getContext(),2));c.drawRect(frame,paint);paint.setStyle(Paint.Style.FILL);}
        @Override public boolean onTouchEvent(MotionEvent e){detector.onTouchEvent(e);switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:requestFocus();lastX=e.getX();lastY=e.getY();return true;case MotionEvent.ACTION_POINTER_UP:int keep=e.getActionIndex()==0?1:0;if(keep<e.getPointerCount()){lastX=e.getX(keep);lastY=e.getY(keep);}break;case MotionEvent.ACTION_MOVE:if(!detector.isInProgress()&&e.getPointerCount()==1)move(e.getX()-lastX,e.getY()-lastY);lastX=e.getX();lastY=e.getY();break;case MotionEvent.ACTION_UP:performClick();break;}return true;}
        @Override public boolean onKeyDown(int key,android.view.KeyEvent event){switch(key){case 19:move(0,-CarUi.dp(getContext(),12));return true;case 20:move(0,CarUi.dp(getContext(),12));return true;case 21:move(-CarUi.dp(getContext(),12),0);return true;case 22:move(CarUi.dp(getContext(),12),0);return true;case 69:zoom(.9f,frame.centerX(),frame.centerY());return true;case 70:case 81:zoom(1.1f,frame.centerX(),frame.centerY());return true;}return super.onKeyDown(key,event);}
        @Override public boolean performClick(){super.performClick();return true;}
        Bitmap output(){if(image==null||frame.width()<=0)throw new IllegalStateException();int[] size=outputSize(targetW,targetH);Bitmap b=Bitmap.createBitmap(size[0],size[1],Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);canvas.drawColor(Color.BLACK);canvas.scale(size[0]/frame.width(),size[1]/frame.height());canvas.translate(-frame.left,-frame.top);canvas.drawBitmap(image,matrix(),new Paint(3));return b;}
        void release(){Bitmap previous=image;image=null;if(previous!=null&&!previous.isRecycled())previous.recycle();}
    }
}
